    predicate: impl FnOnce(&mut T) -> bool,
) -> (result: Option<T>)
    requires
        old(v)@.len() > 0 ==> forall|x: &mut T|
            *x == old(v)@[0] ==> predicate.requires((x,)),
    ensures
        old(v)@.len() == 0 ==> result is None && final(v)@ == old(v)@,
        old(v)@.len() > 0 ==> exists|x: &mut T, take: bool| {
            &&& *x == old(v)@[0]
            &&& predicate.ensures((x,), take)
            &&& (take ==> {
                &&& result == Some(*final(x))
                &&& final(v)@ == old(v)@.subrange(1, old(v)@.len())
            })
            &&& (!take ==> {
                &&& result is None
                &&& final(v)@ == old(v)@.update(0, *final(x))
            })
        },
;

pub assume_specification<T, F: FnOnce(&T, &T) -> core::cmp::Ordering>[ core::cmp::max_by ](
    v1: T,
    v2: T,
    compare: F,
) -> (result: T)
    requires
        compare.requires((&v1, &v2)),
    ensures
        exists|ordering: core::cmp::Ordering| {
            &&& #[trigger] compare.ensures((&v1, &v2), ordering)
            &&& result == if ordering == core::cmp::Ordering::Greater { v1 } else { v2 }
        },
;

pub assume_specification<T, F, K>[ core::cmp::max_by_key ](
    v1: T,
    v2: T,
    f: F,
) -> (result: T)
where
    F: FnMut(&T) -> K,
    K: core::cmp::Ord,
    requires
        f.requires((&v2,)),
        f.requires((&v1,)),
    ensures
        exists|key2: K| {
            &&& #[trigger] f.ensures((&v2,), key2)
            &&& exists|key1: K| {
                &&& #[trigger] f.ensures((&v1,), key1)
                &&& exists|is_less: bool| {
                    &&& #[trigger] call_ensures(
                        <K as core::cmp::PartialOrd>::lt,
                        (&key2, &key1),
                        is_less,
                    )
                    &&& result == if is_less { v1 } else { v2 }
                }
            }
        },
;

