fn cmp<I>(self, other: I) -> (r: Ordering)
    where
        I: core::iter::IntoIterator<Item = Self::Item>,
        Self::Item: Ord,
        Self: Sized,
    default_ensures
        self.obeys_prophetic_iter_laws()
            && self.initial_value_relation(&self)
            && <Self::Item as OrdSpec>::obeys_cmp_spec()
            ==> {
                let left = self.remaining();
                let right = into_iter_remaining::<Self::Item, I>(other);
                match r {
                    Ordering::Equal => {
                        &&& left.len() == right.len()
                        &&& forall |i: int| 0 <= i < left.len() ==>
                            <Self::Item as OrdSpec>::cmp_spec(&left[i], &right[i]) == Ordering::Equal
                    },
                    Ordering::Less =>
                        (exists |i: int| {
                            &&& 0 <= i < left.len()
                            &&& 0 <= i < right.len()
                            &&& forall |j: int| 0 <= j < i ==>
                                <Self::Item as OrdSpec>::cmp_spec(&left[j], &right[j]) == Ordering::Equal
                            &&& <Self::Item as OrdSpec>::cmp_spec(&left[i], &right[i]) == Ordering::Less
                        })
                        || (left.len() < right.len()
                            && forall |i: int| 0 <= i < left.len() ==>
                                <Self::Item as OrdSpec>::cmp_spec(&left[i], &right[i]) == Ordering::Equal),
                    Ordering::Greater =>
                        (exists |i: int| {
                            &&& 0 <= i < left.len()
                            &&& 0 <= i < right.len()
                            &&& forall |j: int| 0 <= j < i ==>
                                <Self::Item as OrdSpec>::cmp_spec(&left[j], &right[j]) == Ordering::Equal
                            &&& <Self::Item as OrdSpec>::cmp_spec(&left[i], &right[i]) == Ordering::Greater
                        })
                        || (right.len() < left.len()
                            && forall |i: int| 0 <= i < right.len() ==>
                                <Self::Item as OrdSpec>::cmp_spec(&left[i], &right[i]) == Ordering::Equal),
                }
            },
;

