pub assume_specification<T, A: Allocator>[
    Box::<MaybeUninit<T>, A>::assume_init
](
    boxed: Box<MaybeUninit<T>, A>,
) -> (res: Box<T, A>)
    requires
        boxed.mem_contents().is_init(),
    ensures
        *res == boxed.mem_contents().value(),
;

pub assume_specification[ CString::into_raw ](
    this: CString,
) -> (result: *mut c_char)
    ensures
        result.addr() != 0,
;

pub assume_specification<T: ?Sized, A: Allocator>[ Rc::<T, A>::as_ptr ](
    this: &Rc<T, A>,
) -> (result: *const T)
    ensures
