;

pub assume_specification<T: ?Sized>[ core::cell::Cell::<T>::as_ptr ](
    this: &core::cell::Cell<T>,
) -> (ptr: *mut T)
    ensures
        ptr@.addr != 0,
;

pub assume_specification<T: ?Sized>[ core::cell::RefCell::<T>::as_ptr ](
    this: &core::cell::RefCell<T>,
) -> (ptr: *mut T)
    ensures
