;

pub assume_specification<T>[ MaybeUninit::<T>::as_ptr ](
    this: &MaybeUninit<T>,
) -> (result: *const T)
    ensures
        result == this as *const MaybeUninit<T> as *const T,
;

pub assume_specification<'a, T: Copy>[ Option::<&'a T>::copied ](opt: Option<&'a T>) -> (res: Option<T>)
    ensures
        res == (match opt {
            Some(v) => Some(*v),
            None => None,
        }),
    no_unwind
;

pub assume_specification<T: core::marker::PointeeSized>[
    core::ptr::NonNull::<T>::new
](ptr: *mut T) -> (result: Option<core::ptr::NonNull<T>>)
    ensures
        (result is Some) <==> ptr@.addr != 0,
;

pub assume_specification<T: core::marker::PointeeSized>[<*mut T>::addr](
    p: *mut T,
) -> (address: usize)
    ensures
        address == p@.addr,
;

pub assume_specification<T, const N: usize>[<*const [T]>::as_array::<N>](
    p: *const [T],
) -> (result: Option<*const [T; N]>)
    ensures
        result == if p@.metadata == N {
            Some(ptr_from_data::<[T; N]>(PtrData::<[T; N]> {
                addr: p@.addr,
                provenance: p@.provenance,
                metadata: (),
            }))
        } else {
            None
        },
;

pub assume_specification<T, const N: usize>[ <*mut [T]>::as_mut_array::<N> ](
    ptr: *mut [T],
) -> (result: Option<*mut [T; N]>)
    ensures
        result == if ptr@.metadata == N {
            Some(ptr as *mut [T; N])
        } else {
            None
        },
;

pub assume_specification<T>[
    <*const [T]>::is_empty
](ptr: *const [T]) -> (result: bool)
    ensures
        result <==> ptr@.metadata == 0,
;

pub assume_specification<T: core::marker::PointeeSized>[
    <*const T>::is_null
](ptr: *const T) -> (result: bool)
    ensures
        result <==> ptr@.addr == 0,
;

pub assume_specification<T>[
    <*const [T]>::len
](ptr: *const [T]) -> (result: usize)
    ensures
        result == ptr@.metadata,
;

pub assume_specification<T: Copy, E>[ Result::<&T, E>::copied ](
    result: Result<&T, E>,
) -> (res: Result<T, E>)
    ensures
        res == match result {
            Result::Ok(value) => Result::Ok(*value),
            Result::Err(error) => Result::Err(error),
        },
;
